    }
    let expanded = self.expanded().map(|ask| ask.id);
    let history_row =
        (self.on_ask_tab && !self.ask_history_shown()).then(|| self.render_ask_history_row(cx));
    let ids: Vec<usize> = self
        .asks
        .iter()
        .filter(|ask| expanded != Some(ask.id))
        .map(|ask| ask.id)

