        let history = bounds_of(handle, "history", cx).unwrap();
        assert!(history.size.height < whole.size.height, "the stack covers the task view");

        prompt_mode.update(cx, |this, cx| {
            this.on_ask_tab = true;
            cx.notify();
        });
        frames(handle, cx);
        assert!(bounds_of(handle, "ask", cx).is_none(), "the stack shows on the Ask tab");
        assert!(bounds_of(handle, ("question", super::ASK_IX - 1), cx).is_some());
        cx.update_window(handle, |_, window, cx| {
